{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.product_journey as ( with price as ( select distinct LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' in REVERSE(value:sku::STRING))) as sku_group, ifnull(value:compareAtPrice::NUMBER,0)::int as compare_at_price, value:price::NUMBER::int as price from snitch_db.maplemonk.new_meafields_product_products_graph_ql, lateral flatten(input => parse_json(variants)) as value ), final_price1 as ( select sku_group, greatest(compare_at_price,price) AS db_original_price, CASE WHEN compare_at_price != 0 THEN LEAST(compare_at_price,price) ELSE GREATEST(price,compare_at_price) END AS db_slashed_price from price ), final_price as ( select sku_group, db_original_price as original_price, db_slashed_price as current_slashed_price, from final_price1 where sku_group not in (\'\',\'1290\') qualify row_number() over (partition by sku_group order by db_original_price desc) = 1 ), live_date_pre as ( select LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, min(PUBLISHEDAT::date) as live_date, lower(status) as status from snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value group by 1,3 ), sku_count as ( select sku_group, count(*) as status_count from live_date_pre group by 1 ), live_date_main as ( select upper(trim(a.sku_group)) as sku_group, a.status, live_date, row_number() over (partition by a.sku_group order by a.live_date desc) as rn, b.status_count from live_date_pre a left join sku_count b on a.sku_group = b.sku_group ), final_live_date_pre as ( select sku_group, status, live_date as final_live_date from live_date_main where (status_count > 1 and rn = 2) or (status_count = 1 and rn = 1) ), first_sales as ( select sku_group, min(order_timestamp::date) as first_order_date from snitch_db.maplemonk.fact_items_snitch group by 1 ), final_live_date as ( select a.sku_group, a.status, case when b.first_order_date is null then a.final_live_date when a.final_live_date is null then b.first_order_date else least(a.final_live_date,b.first_order_date) end as final_live_date from final_live_date_pre a left join first_sales b on a.sku_group =b.sku_group ), sales_data as ( select case when UPPER(TRIM(a.sku_group)) like \'BP%\' then split_part(UPPER(TRIM(a.sku_group)),\'-\',0) else UPPER(TRIM(a.sku_group)) end as sku_group, ifnull(sum(case when type = \'Store\' then gross_quantity end),0) as store_quant, ifnull(sum(case when type = \'Shopify\' then gross_quantity end),0) as shopify_quant, ifnull(sum(case when type = \'Markteplace\' then gross_quantity end),0) as marketplace_quant, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as store_quant7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as shopify_quant7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_quantity end),0) as marketplace_quant7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as store_quant30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as shopify_quant30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_quantity end),0) as marketplace_quant30, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as store_sales7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as shopify_sales7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then gross_sales end),0) as marketplace_sales7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as store_sales30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as shopify_sales30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then gross_sales end),0) as marketplace_sales30, ifnull(sum(case when type = \'Store\' then gross_sales end),0) as store_sales, ifnull(sum(case when type = \'Shopify\' then gross_sales end),0) as shopify_sales, ifnull(sum(case when type = \'Marketplace\' then gross_sales end),0) as marketplace_sales, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as store_discount7, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as shopify_discount7, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=8 then discount_amount end),0) as marketplace_discount7, ifnull(sum(case when type = \'Store\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as store_discount30, ifnull(sum(case when type = \'Shopify\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as shopify_discount30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,date,current_date) <=31 then discount_amount end),0) as marketplace_discount30, ifnull(sum(case when type = \'Store\' then discount_amount end),0) as store_discount, ifnull(sum(case when type = \'Shopify\' then discount_amount end),0) as shopify_discount, ifnull(sum(case when type = \'Marketplace\' then discount_amount end),0) as marketplace_discount, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.final_live_date,date) <=31 then gross_quantity end),0) as marketplace_quant_first30, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.final_live_date,date) <=31 then gross_quantity end),0) as shopify_quant_first30, ifnull(sum(case when type = \'Marketplace\' and datediff(day,b.final_live_date,date) <=61 then gross_quantity end),0) as marketplace_quant_first60, ifnull(sum(case when type = \'Shopify\' and datediff(day,b.final_live_date,date) <=61 then gross_quantity end),0) as shopify_quant_first60 from snitch_db.maplemonk.horizontal_sales_categories a left join final_live_date b on case when UPPER(TRIM(a.sku_group)) like \'BP%\' then split_part(UPPER(TRIM(a.sku_group)),\'-\',0) else UPPER(TRIM(a.sku_group)) end = upper(trim(b.sku_group)) group by 1 ), aging as ( select upper(trim(SKU_GROUP)) as sku_group, ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'0-30\') then units_on_hand end),0) as \"inv<30\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'60-90\',\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>60\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'90-120\',\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>90\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'120-150\',\'150-180\',\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>120\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'180-210\',\'210-240\',\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>180\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'240-270\',\'270-300\',\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>240\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'300-330\',\'330-360\',\'>360\') then units_on_hand end),0) as \"inv>300\", ifnull(sum(case when \"DAYS_IN_WAREHOUSE_RANGE\" in (\'>360\') then units_on_hand end),0) as \"inv>360\", ifnull(sum(units_on_hand),0) as units_on_hand, round(sum(\"Days in warehouse\"*units_on_hand)/sum(units_on_hand),0) as overall_aging from snitch_db.maplemonk.overall_aging group by 1 ), clicks as ( select upper(trim(sku_group)) as sku_group, sum(case when datediff(day,ga_date,current_date) <=8 then clicks end) clicks_7, sum(case when datediff(day,ga_date,current_date) <=31 then clicks end) clicks_30 from snitch_db.maplemonk.clicks_itemid group by 1 ), inv as ( select upper(trim(sku_group)) as sku_group, product_name, sku_class, sellable_inventory, category, live_date from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by upper(trim(sku_group)) order by sellable_inventory desc) = 1 ), offline_inventory as ( SELECT case when UPPER(TRIM(sku_group)) like \'BP%\' then split_part(UPPER(TRIM(sku_group)),\'-\',0) else UPPER(TRIM(sku_group)) end as sku_group, sum(inventory+JIT_QTY) as offline_inventory, FROM snitch_db.maplemonk.offline_master group by 1 ), design as ( select upper(trim(sku_group)) as sku_group, case when div0(FIRST_30D_SALES,INVENTORY) < 0.3 and HIT_SIZES < 3 then \'hit\' else \'non_hit\' end as strike, inventory as starting_inventory from snitch_db.maplemonk.design_fact_items qualify row_number() over (partition by upper(trim(sku_group)) order by starting_inventory desc) = 1 ), inwards as ( select upper(trim(LEFT(\"Item Type skuCode\", LENGTH(\"Item Type skuCode\") - CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\"))))) AS sku_group, putaway_updated::date as inward_date, sum(putaway_completed_quantity) as inward_quantity from snitch_db.maplemonk.putaway_tracking where final_type = \'New Inward\' group by 1,2 having sum(putaway_completed_quantity) > 50 ), inwards_data as ( select upper(trim(sku_group)) as sku_group, count(distinct date_trunc(month,inward_date)) as inward_count, max(inward_date) as last_inward, datediff(day,max(inward_date),current_date) as days_since_inward from inwards group by 1 ), returns as ( select upper(trim(sku_group)) as sku_group, round(sum(case when datediff(day,order_date,current_date) <=31 then return_qty end),0) shopify_return_30, round(sum(case when datediff(day,order_date,current_date) <=8 then return_qty end),0) shopify_return_7, from snitch_db.maplemonk.return_fact_items group by 1 ), cost_price as ( select case when UPPER(TRIM(SKUGROUP)) like \'BP%\' then split_part(UPPER(TRIM(SKUGROUP)),\'-\',0) else UPPER(TRIM(SKUGROUP)) end as sku_group, max(cost_price) as cost_price from snitch_db.maplemonk.uc_final_item_master group by 1 ), images as ( select sku_group, preview_image as image, from snitch_db.maplemonk.products_db_copy where sku_group is not null qualify row_number() over (partition by sku_group order by status desc) = 1 ), main_data AS ( SELECT a.sku_group, a.sku_class, a.category, a.sellable_inventory AS current_inventory, a.product_name, o.offline_inventory, DATEDIFF(DAY, e.final_live_date, CURRENT_DATE) AS days_live, e.status, b.original_price, b.current_slashed_price, c.\"inv<30\", c.\"inv>60\", c.\"inv>90\", c.\"inv>120\", c.\"inv>180\", c.\"inv>240\", c.\"inv>300\", c.\"inv>360\", c.overall_aging, c.units_on_hand, IFNULL(d.store_quant, 0) AS store_quant, IFNULL(d.shopify_quant, 0) AS shopify_quant, IFNULL(d.marketplace_quant, 0) AS marketplace_quant, IFNULL(d.store_quant7, 0) AS store_quant7, IFNULL(d.shopify_quant7, 0) AS shopify_quant7, IFNULL(d.marketplace_quant7, 0) AS marketplace_quant7, IFNULL(d.store_quant30, 0) AS store_quant30, IFNULL(d.shopify_quant30, 0) AS shopify_quant30, IFNULL(d.marketplace_quant30, 0) AS marketplace_quant30, IFNULL(d.store_sales7, 0) AS store_sales7, IFNULL(d.shopify_sales7, 0) AS shopify_sales7, IFNULL(d.marketplace_sales7, 0) AS marketplace_sales7, IFNULL(d.store_sales30, 0) AS store_sales30, IFNULL(d.shopify_sales30, 0) AS shopify_sales30, IFNULL(d.marketplace_sales30, 0) AS marketplace_sales30, IFNULL(d.store_sales, 0) AS store_sales, IFNULL(d.shopify_sales, 0) AS shopify_sales, IFNULL(d.marketplace_sales, 0) AS marketplace_sales, IFNULL(d.store_discount7, 0) AS store_discount7, IFNULL(d.shopify_discount7, 0) AS shopify_discount7, IFNULL(d.marketplace_discount7, 0) AS marketplace_discount7, IFNULL(d.store_discount30, 0) AS store_discount30, IFNULL(d.shopify_discount30, 0) AS shopify_discount30, IFNULL(d.marketplace_discount30, 0) AS marketplace_discount30, IFNULL(d.store_discount, 0) AS store_discount, IFNULL(d.shopify_discount, 0) AS shopify_discount, IFNULL(d.marketplace_discount, 0) AS marketplace_discount, IFNULL(f.clicks_30, 0) AS clicks_30, IFNULL(f.clicks_7, 0) AS clicks_7, g.strike, e.final_live_date, IFNULL(h.inward_count, 0) AS inward_count, h.last_inward, h.days_since_inward, i.shopify_return_30, i.shopify_return_7, p.cost_price, im.image FROM inv a LEFT JOIN final_price b ON a.sku_group = b.sku_group LEFT JOIN aging c ON a.sku_group = c.sku_group LEFT JOIN sales_data d ON a.sku_group = d.sku_group LEFT JOIN final_live_date e ON a.sku_group = e.sku_group LEFT JOIN clicks f ON a.sku_group = f.sku_group LEFT JOIN design g ON a.sku_group = g.sku_group LEFT JOIN inwards_data h ON a.sku_group = h.sku_group LEFT JOIN returns i ON a.sku_group = i.sku_group left join offline_inventory o on a.sku_group = o.sku_group left join cost_price p on a.sku_group = p.sku_group left join images im on a.sku_group = im.sku_group WHERE a.sellable_inventory IS NOT NULL AND a.sellable_inventory != 0 ), metafields as ( select sku_group, product_tags, style from snitch_db.maplemonk.metafields_data qualify row_number() over (partition by sku_group order by product_tags desc) = 1 ), duplicate_check as ( SELECT a.sku_group, a.product_name, a.category, image, status, current_inventory AS inventory, offline_inventory, original_price, current_slashed_price, cost_price, inward_count, days_since_inward, last_inward, final_live_date, DATEDIFF(DAY, final_live_date, CURRENT_DATE) AS days_since_live, store_sales30, shopify_sales30, marketplace_sales30, store_sales7, shopify_sales7, marketplace_sales7, CASE WHEN units_on_hand <> 0 THEN \"inv>60\" / units_on_hand ELSE 0 END AS inv_60, CASE WHEN units_on_hand <> 0 THEN \"inv>90\" / units_on_hand ELSE 0 END AS inv_90, CASE WHEN units_on_hand <> 0 THEN \"inv>120\" / units_on_hand ELSE 0 END AS inv_120, CASE WHEN units_on_hand <> 0 THEN \"inv>180\" / units_on_hand ELSE 0 END AS inv_180, CASE WHEN units_on_hand <> 0 THEN \"inv>240\" / units_on_hand ELSE 0 END AS inv_240, CASE WHEN units_on_hand <> 0 THEN \"inv>300\" / units_on_hand ELSE 0 END AS inv_300, CASE WHEN units_on_hand <> 0 THEN \"inv>360\" / units_on_hand ELSE 0 END AS inv_360, overall_aging, shopify_return_7, shopify_return_30, store_quant, shopify_quant, marketplace_quant, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN store_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS store_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN shopify_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS shopify_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN (shopify_quant7 - shopify_return_7) / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS net_shopify_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN marketplace_quant7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS marketplace_ros_7, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN store_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS store_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN shopify_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS shopify_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN (shopify_quant30 - shopify_return_30) / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS net_shopify_ros_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN marketplace_quant30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS marketplace_ros_30, CASE WHEN (store_discount7 + store_sales7) <> 0 THEN (store_discount7 / (store_discount7 + store_sales7)) * 100 ELSE 0 END AS store_discount_7_percentage, CASE WHEN (store_discount30 + store_sales30) <> 0 THEN (store_discount30 / (store_discount30 + store_sales30)) * 100 ELSE 0 END AS store_discount_30_percentage, CASE WHEN (shopify_discount7 + shopify_sales7) <> 0 THEN (shopify_discount7 / (shopify_discount7 + shopify_sales7)) * 100 ELSE 0 END AS shopify_discount_7_percentage, CASE WHEN (shopify_discount30 + shopify_sales30) <> 0 THEN (shopify_discount30 / (shopify_discount30 + shopify_sales30)) * 100 ELSE 0 END AS shopify_discount_30_percentage, CASE WHEN (marketplace_discount7 + marketplace_sales7) <> 0 THEN (marketplace_discount7 / (marketplace_discount7 + marketplace_sales7)) * 100 ELSE 0 END AS marketplace_discount_7_percentage, CASE WHEN (marketplace_discount30 + marketplace_sales30) <> 0 THEN (marketplace_discount30 / (marketplace_discount30 + marketplace_sales30)) * 100 ELSE 0 END AS marketplace_discount_30_percentage, CASE WHEN (store_discount + store_sales) <> 0 THEN (store_discount / (store_discount + store_sales)) * 100 ELSE 0 END AS store_discount_percentage, CASE WHEN (shopify_discount + shopify_sales) <> 0 THEN (shopify_discount / (shopify_discount + shopify_sales)) * 100 ELSE 0 END AS shopify_discount_percentage, CASE WHEN (marketplace_discount + marketplace_sales) <> 0 THEN (marketplace_discount / (marketplace_discount + marketplace_sales)) * 100 ELSE 0 END AS marketplace_discount_percentage, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN clicks_30 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 30) ELSE 0 END AS clicks_rate_30, CASE WHEN DATEDIFF(DAY, final_live_date, CURRENT_DATE) > 0 THEN clicks_7 / LEAST(DATEDIFF(DAY, final_live_date, CURRENT_DATE), 7) ELSE 0 END AS clicks_rate_7, b.product_tags, b.style, strike FROM main_data a left join metafields b on a.sku_group = b.sku_group ) select *, case when last_inward is null then inward_count WHEN LAST_INWARD BETWEEN DATEADD(day, -30, final_live_date) AND DATEADD(day, 30, final_live_date) THEN inward_count else inward_count +1 end as inward_count_real from duplicate_check qualify row_number() over (partition by sku_group order by inventory desc )= 1 );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
